import{_ as o,a8 as a,o as r,c as s,ah as _,K as l}from"./chunks/framework.tJjSirE1.js";import"./chunks/theme.BFhW3K9V.js";const A=JSON.parse('{"title":"费曼学习法2.0-四阶段学习流程","description":"","frontmatter":{"title":"费曼学习法2.0-四阶段学习流程","abstract":"把费曼学习法从“讲给别人听”扩展为输入、讲授、复盘、内化与再简化四个阶段，并用 AI 解决听众、反馈和专家审阅问题。","created":"2026-10-19T00:00:00.000Z","updated":"2026-10-22T00:00:00.000Z","tags":["费曼学习法","学习方法","AI辅助学习","输出倒逼输入"],"type":"步骤操作","related":["[[6.个人能力-MOC]]","[[📚 个人知识管理-MOC]]","[[05-输出与创作]]","[[搭建知识体系：七大学习模型]]","[[主动回忆法]]","[[费曼学习法-AI讲解与复盘提示词]]"],"reference":["[[Resources/学习与个人成长/B站-月小小吖/费曼学习法2.0-视频文字稿]]","[[Resources/学习与个人成长/B站-月小小吖/费曼学习法2.0-画面OCR]]"],"source_type":"视频教程","source_url":"https://www.bilibili.com/video/BV1qBV661E7a/","category":["📚 个人知识管理","个人能力"]},"headers":[],"relativePath":"vault/Knowledge/Methods/费曼学习法2.0-四阶段学习流程.md","filePath":"vault/Knowledge/Methods/费曼学习法2.0-四阶段学习流程.md","lastUpdated":1793186727000}'),n={name:"vault/Knowledge/Methods/费曼学习法2.0-四阶段学习流程.md"};function d(c,e,h,p,u,b){const i=a("NolebaseGitContributors"),t=a("NolebaseGitChangelog");return r(),s("div",null,[e[0]||(e[0]=_('<h1 id="费曼学习法2-0-四阶段学习流程" tabindex="-1">费曼学习法2.0-四阶段学习流程 <a class="header-anchor" href="#费曼学习法2-0-四阶段学习流程" aria-label="Permalink to “费曼学习法2.0-四阶段学习流程”">​</a></h1><p>本文整理视频作者提出的四阶段学习闭环，依据为 ASR 与抽帧 OCR，尚未逐句回溯原始音画；具体时长是作者建议，不代表经本笔记核实的科学结论。</p><h2 id="_1-输入-为目标、精力与结构做准备" tabindex="-1">1. 输入：为目标、精力与结构做准备 <a class="header-anchor" href="#_1-输入-为目标、精力与结构做准备" aria-label="Permalink to “1. 输入：为目标、精力与结构做准备”">​</a></h2><ul><li>以好奇心和长期理解为目标，不只看是否能立即变现。</li><li>目标要具体、可量化、难度适中，并有明确期限。</li><li>作者建议学习一份新材料约 30～50 分钟，过程中给注意力留恢复空间，并选择个人效率较高的时段。</li><li>先看整体框架，再联系已有知识，带着问题进入细节。</li><li>阅读时把重点、联想、疑问和吐槽用语音即时交给 AI，让 AI做阶段性整理。</li></ul><h2 id="_2-讲授-把知识讲给-不懂的人" tabindex="-1">2. 讲授：把知识讲给“不懂的人” <a class="header-anchor" href="#_2-讲授-把知识讲给-不懂的人" aria-label="Permalink to “2. 讲授：把知识讲给“不懂的人””">​</a></h2><ul><li>按细小知识块组织，不把一大段内容一口气倒给对方。</li><li>单次讲解尽量控制在 10 分钟内。</li><li>用生活化例子、大白话和清晰的前后关系说明。</li><li>可用 AI 扮演 8 岁小学生，持续追问“这是什么意思”“然后呢”，并记录卡壳点。</li></ul><h2 id="_3-复盘-区分记忆、理解与视野问题" tabindex="-1">3. 复盘：区分记忆、理解与视野问题 <a class="header-anchor" href="#_3-复盘-区分记忆、理解与视野问题" aria-label="Permalink to “3. 复盘：区分记忆、理解与视野问题”">​</a></h2><ul><li>记忆问题：回看材料、重复记忆。</li><li>理解问题：拆解底层逻辑、应用场景和前后因果。</li><li>视野问题：做横向类比、纵向追本溯源，补充跨学科联系。</li><li>卡住、心虚、啰嗦和讲不清的地方，正是需要重学的部位。</li></ul><h2 id="_4-内化-再简化并接受专家检验" tabindex="-1">4. 内化：再简化并接受专家检验 <a class="header-anchor" href="#_4-内化-再简化并接受专家检验" aria-label="Permalink to “4. 内化：再简化并接受专家检验”">​</a></h2><ul><li>第二次、第三次讲述时，目标从“讲出来”升级为“打散、重组、深入浅出”。</li><li>删掉不必要的铺垫、黑话和解释，只保留核心骨架。</li><li>按作者建议，用 AI 专家或提供资料后的 NotebookLM 追问本质、前提和边界。</li><li>复盘后把结论回写笔记，形成下一轮输入。</li></ul><p>核心闭环：<code>输入 → 讲授 → 暴露盲区 → 复盘重学 → 再简化讲授</code>。</p><blockquote><p>整理者提醒：时长按自身状态调整；AI 回答仍须回到资料核对。</p></blockquote>',12)),l(i),l(t)])}const C=o(n,[["render",d]]);export{A as __pageData,C as default};
